Here's a Python function that filters EC2 instances based on state and tags:

```python
def filter_production_running_instances(instances):
    """
    Filter EC2 instances that are running and tagged as production environment.

    Args:
        instances: List of EC2 instance dictionaries

    Returns:
        List of instances that are in 'running' state and have 
        Environment tag set to 'production'
    """
    filtered_instances = []

    for instance in instances:
        # Check if instance is in running state
        if instance.get('State', {}).get('Name') != 'running':
            continue

        # Check for Environment=production tag
        tags = instance.get('Tags', [])
        has_production_tag = False

        for tag in tags:
            if tag.get('Key') == 'Environment' and tag.get('Value') == 'production':
                has_production_tag = True
                break

        if has_production_tag:
            filtered_instances.append(instance)

    return filtered_instances
```

**Alternative implementation using list comprehension:**

```python
def filter_production_running_instances(instances):
    """
    Filter EC2 instances that are running and tagged as production environment.
    """
    def is_production_running(instance):
        # Check running state
        is_running = instance.get('State', {}).get('Name') == 'running'

        # Check for production tag
        tags = instance.get('Tags', [])
        is_production = any(
            tag.get('Key') == 'Environment' and tag.get('Value') == 'production'
            for tag in tags
        )

        return is_running and is_production

    return [instance for instance in instances if is_production_running(instance)]
```

